for f in tmp/knmiet-verify.BJqRY0/engineering.html tmp/knmiet-verify.BJqRY0/overall.html; do
  printf '%s\\n' \"--- "'$f exact candidate lines ---"
  rg -in -C 3 '"'MODI|K\\.N\\.|MODINAGAR' \""'$f" || true
done
printf '"'%s\\n' '--- parsed matching rows ---'
python3 - <<'PY'
from html.parser import HTMLParser
from pathlib import Path
class P(HTMLParser):
    def __init__(self): super().__init__(); self.rows=[]; self.row=[]; self.cell=[]; self.in_td=False
    def handle_starttag(self,t,a):
        if t=='tr': self.row=[]
        elif t=='td': self.cell=[]; self.in_td=True
    def handle_endtag(self,t):
        if t=='td': self.row.append(' '.join(''.join(self.cell).split())); self.in_td=False
        elif t=='tr' and self.row: self.rows.append(self.row)
    def handle_data(self,d):
        if self.in_td: self.cell.append(d)
for name in ['engineering.html','overall.html']:
    p=P(); p.feed(Path('tmp/knmiet-verify.BJqRY0',name).read_text(errors='ignore'))
    print(name)
    for row in p.rows:
        s=' | '.join(row)
        if any(x in s.lower() for x in ['modi','k.n.','modinagar']): print(s)
PY"

