q='\"K.N. Modi\" Modinagar'; enc="'$(python3 -c '"'import urllib.parse,sys; print(urllib.parse.quote(sys.argv[1]))' \""'$q"); f=$(mktemp "$TMPDIR/knmiet-bing.XXXXXX.html"); curl -k -L --fail --max-time 25 -A '"'Mozilla/5.0' \"https://www.bing.com/search?q="'$enc&adlt=off&count=20" -o "$f" >/dev/null
python3 - "$f" <<'"'PY'
from html.parser import HTMLParser
from pathlib import Path
import html, base64, urllib.parse
class P(HTMLParser):
    def __init__(self): super().__init__(); self.in_li=False; self.in_h2=False; self.in_a=False; self.cur=None; self.results=[]
    def handle_starttag(self,t,a):
        d=dict(a)
        if t=='li' and 'b_algo' in d.get('class',''):
            self.in_li=True; self.cur={'href':None,'title':[],'text':[]}
        elif self.in_li and t=='h2': self.in_h2=True
        elif self.in_li and t=='a' and self.in_h2: self.cur['href']=d.get('href'); self.in_a=True
        elif self.in_li and t=='p': self.cur['p']=[]
    def handle_endtag(self,t):
        if self.in_li and t=='a' and self.in_a: self.in_a=False
        elif self.in_li and t=='h2': self.in_h2=False
        elif self.in_li and t=='li': self.results.append(self.cur); self.in_li=False
    def handle_data(self,d):
        if not self.in_li: return
        if self.in_h2: self.cur['title'].append(d)
        if 'p' in self.cur: self.cur['p'].append(d)
p=P(); p.feed(Path(__import__('sys').argv[1]).read_text(errors='ignore'))
print('count',len(p.results))
for i,r in enumerate(p.results,1):
    print(i, 'TITLE=', ' '.join(''.join(r['title']).split()))
    print(' URL=', html.unescape(r['href'] or ''))
    print(' DESC=', ' '.join(r.get('p',[])).strip())
PY"

